                            if 0<=x<H and 0<=y<W and din[x][y]!=bg and (x,y) not in cc: st.append((x,y))
                seen|=cc
                if len(cc)>1: tmpl.append(sorted([(a,b,din[a][b]) for a,b in cc]))
    tset=set().union(*[{(a,b) for a,b,v in t} for t in tmpl])
