                        rr,cc=s[0]+da,s[1]+db
                        if 0<=rr<H and 0<=cc<W and din[rr][cc]==bg: pred.add(((rr,cc),w))
                cov=sum(1 for p,w in pred if (p,w) in added.values())
                wrong=sum(1 for p,w in pred if p in added and added[p]!=w)
