def comps_of(g,bg):
    Hh,Ww=len(g),len(g[0]); seen=set(); out=[]
    for r in range(Hh):
        for c in range(Ww):
            if g[r][c]!=bg and (r,c) not in seen:
                st=[(r,c)];cc=set()
                while st:
                    a,b=st.pop()
                    if (a,b) in cc:continue
                    cc.add((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            x,y=a+da,b+db
                            if 0<=x<Hh and 0<=y<Ww and g[x][y]!=bg and (x,y) not in cc: st.append((x,y))
                seen|=cc; out.append(sorted(cc))
    return out
